import{_ as r,o as t,c as e,a2 as i}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"일반 설정","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/general.md","filePath":"ko-KR/user-guide/settings/general.md","lastUpdated":1788247711000}'),n={name:"ko-KR/user-guide/settings/general.md"};function a(s,o,l,d,g,c){return t(),e("div",null,[...o[0]||(o[0]=[i('<h1 id="일반-설정" tabindex="-1">일반 설정 <a class="header-anchor" href="#일반-설정" aria-label="Permalink to &quot;일반 설정&quot;">​</a></h1><p>일반 설정에서는 Lertaro의 핵심 시스템 동작, 검색창의 픽셀 단위 크기 및 레이아웃, 결과 유형별 우선순위, 미리보기 제공자 순서 등을 관리합니다. 상단에는 <strong>시스템</strong>, <strong>퀵 검색 윈도우</strong>, <strong>메인 검색 윈도우</strong>, <strong>미리보기 윈도우</strong>, <strong>퀵 내비게이션</strong>, <strong>미리보기 및 썸네일</strong>의 6개 탭이 제공됩니다.</p><h2 id="_1-시스템-system" tabindex="-1">1. 시스템 (System) <a class="header-anchor" href="#_1-시스템-system" aria-label="Permalink to &quot;1. 시스템 (System)&quot;">​</a></h2><ul><li><strong>Windows 시작 시 자동 실행</strong>: Windows 로그인 시 Lertaro를 자동 실행합니다.</li><li><strong>시작 시 자동 업데이트 확인</strong>: 앱 실행 시 최신 버전이 있는지 온라인으로 자동 확인합니다.</li><li><strong>무음 자동 업데이트</strong>: &quot;업데이트 확인&quot;이 켜져 있을 때 활성화되며, 백그라운드에서 조용히 다운로드하고 팝업 없이 즉시 덮어쓰기 업데이트합니다.</li><li><strong>하드웨어 가속 사용</strong>: 기본 활성화. 듀얼 GPU 노트북(예: NVIDIA Advanced Optimus)에서 Lertaro로 인해 내장 그래픽 자동 전환이 차단되는 경우 소프트웨어 렌더링으로 전환할 수 있습니다. 변경 후 재시작이 필요합니다.</li><li><strong>트레이 아이콘 숨기기</strong>: 작업 표시줄 알림 영역의 아이콘을 숨깁니다. 퀵 검색바 내부의 로고를 클릭하면 동일한 트레이 메뉴가 열리므로 진입점이 사라지지 않습니다.</li><li><strong>Everything 호환 서비스 (IPC) 활성화</strong>: 표준 Everything Win32 IPC 프로토콜을 에뮬레이트하여 Directory Opus, Total Commander 등에서 Lertaro 메모리 인덱스를 직접 호출할 수 있도록 합니다.</li><li><strong>퍼지 매칭 활성화</strong>: 기본 활성화. 연속되지 않은 문자 점프 매칭을 지원하며, 끄면 연속된 부분 문자열만 일치시킵니다(<a href="./../search-syntax.html"><strong>검색 문법</strong></a> 참고). 즉시 적용됩니다.</li><li><strong>쿼리 토큰 접두 문자</strong>: 1자리 텍스트 상자(기본값 <code>:</code>). 검색어 끝의 속성 토큰(예: <code>:.pdf</code>, <code>:@doc</code>, <code>:[S]</code>)의 기준 문자를 지정합니다.</li><li><strong>로그 레벨</strong>: &quot;오류 / 경고 / 정보 (기본값) / 디버그&quot; 중 선택하여 프로세스별 로그 출력 상세도를 제어합니다.</li><li><strong>UI 언어</strong>: 앱 전체의 표시 언어를 선택합니다.</li></ul><h2 id="_2-퀵-검색-윈도우-quick-search-window" tabindex="-1">2. 퀵 검색 윈도우 (Quick Search Window) <a class="header-anchor" href="#_2-퀵-검색-윈도우-quick-search-window" aria-label="Permalink to &quot;2. 퀵 검색 윈도우 (Quick Search Window)&quot;">​</a></h2><p>화면 중앙에 뜨는 퀵 검색바의 크기와 결과 우선순위를 세밀하게 조정합니다.</p><h3 id="검색바-레이아웃" tabindex="-1">검색바 레이아웃 <a class="header-anchor" href="#검색바-레이아웃" aria-label="Permalink to &quot;검색바 레이아웃&quot;">​</a></h3><ul><li><strong>검색바 너비 (픽셀)</strong>: 설정 범위 <code>300–1200px</code>, 기본값 <code>570px</code>.</li><li><strong>검색바 높이 (픽셀)</strong>: 설정 범위 <code>45–120px</code>, 기본값 <code>60px</code>. 이 값에 비례하여 결과 행의 아이콘 크기, 행 높이, 폰트 크기가 자동으로 균형 있게 조절됩니다.</li><li><strong>검색창 내 시계 표시</strong>: 검색어가 비어 있을 때 안내 문구를 현재 날짜, 요일, 시간으로 대체합니다. 입력을 시작하면 자동으로 사라집니다.</li><li><strong>단축키 재입력 시 메인 윈도우 열기</strong>: 퀵 윈도우가 열린 상태에서 호출 단축키를 다시 누르면 현재 검색어를 유지한 채 메인 윈도우로 즉시 전환합니다.</li><li><strong>위치 고정</strong>: 마우스 드래그로 검색바 위치가 이동되는 것을 방지합니다.</li><li><strong>클립보드 텍스트 자동 입력</strong>: 기본적으로 꺼져 있습니다. 퀵 검색 창을 미리 입력된 텍스트 없이 열 때 새롭고 비어 있지 않은 클립보드 텍스트를 검색어로 사용합니다. 수동 붙여넣기와 다른 창에는 영향을 주지 않습니다.</li><li><strong>레이아웃 설정 초기화</strong>: 모든 크기 및 레이아웃을 기본값으로 복원합니다.</li></ul><h3 id="결과-유형-우선순위-및-트리거-문자" tabindex="-1">결과 유형 우선순위 및 트리거 문자 <a class="header-anchor" href="#결과-유형-우선순위-및-트리거-문자" aria-label="Permalink to &quot;결과 유형 우선순위 및 트리거 문자&quot;">​</a></h3><ul><li><strong>우선순위 정렬 목록</strong>: 핸들을 드래그하여 앱, 시스템 설정, 파일, 플러그인 항목의 표시 순서를 변경합니다. 상위에 배치된 유형이 검색 결과에서 더 높은 가중치를 가집니다.</li><li><strong>전용 단일 문자 트리거</strong>: 특정 유형에 단일 문자 접두사(예: 파일 필터에 <code>;</code>)를 부여하여 검색어 맨 앞에 입력 시 해당 유형으로만 즉시 필터링합니다.</li></ul><h2 id="_3-메인-검색-윈도우-full-search-window" tabindex="-1">3. 메인 검색 윈도우 (Full Search Window) <a class="header-anchor" href="#_3-메인-검색-윈도우-full-search-window" aria-label="Permalink to &quot;3. 메인 검색 윈도우 (Full Search Window)&quot;">​</a></h2><p>대화면 메인 검색창(<code>Ctrl+F</code>)의 기본 크기와 테이블 뷰를 설정합니다.</p><ul><li><strong>창 너비 / 높이 (픽셀)</strong>: 너비 <code>640–2000px</code>(기본값 <code>854px</code>), 높이 <code>400–1400px</code>(기본값 <code>480px</code>).</li><li><strong>메인 윈도우 단일 인스턴스 유지</strong>: 켜면 메인 창을 다시 열 때 새 창을 띄우지 않고 기존 창에 포커스를 줍니다.</li><li><strong>검색 윈도우 설정 초기화</strong>: 기본 크기로 복원합니다.</li><li><strong>결과 테이블 열 순서</strong>: 테이블 뷰에서 각 열(이름, 경로, 수정일 등)의 표시 순서를 드래그로 변경합니다.</li><li><strong>사이드바 필터 순서</strong>: 좌측 사이드바 필터 그룹의 순서를 변경하며, 각 분류별 일치 항목 수가 실시간 표시됩니다.</li><li><strong>액션 메뉴 그룹 순서</strong>: <code>Ctrl+O</code> 액션 메뉴 내의 그룹 표시 순서를 조정합니다.</li></ul><h2 id="_4-미리보기-윈도우-preview-window" tabindex="-1">4. 미리보기 윈도우 (Preview Window) <a class="header-anchor" href="#_4-미리보기-윈도우-preview-window" aria-label="Permalink to &quot;4. 미리보기 윈도우 (Preview Window)&quot;">​</a></h2><ul><li><strong>미리보기 너비 / 높이 (픽셀)</strong>: 너비 <code>250–900px</code>, 높이 <code>250–1200px</code>.</li><li><strong>미리보기 설정 초기화</strong>: QuickLook 미리보기 창을 표준 비율로 복원합니다(화면 밖 벗어남 자동 방지).</li></ul><h2 id="_5-퀵-내비게이션-quick-navigation" tabindex="-1">5. 퀵 내비게이션 (Quick Navigation) <a class="header-anchor" href="#_5-퀵-내비게이션-quick-navigation" aria-label="Permalink to &quot;5. 퀵 내비게이션 (Quick Navigation)&quot;">​</a></h2><ul><li><strong>제공자 순서</strong>: 마우스 퀵 내비게이션 계단식 메뉴의 루트 카테고리(즐겨찾기, 기록, 열린 폴더, 파이러 북마크 등) 정렬 순서를 변경합니다.</li></ul><h2 id="_6-미리보기-및-썸네일-previews-thumbnails" tabindex="-1">6. 미리보기 및 썸네일 (Previews &amp; Thumbnails) <a class="header-anchor" href="#_6-미리보기-및-썸네일-previews-thumbnails" aria-label="Permalink to &quot;6. 미리보기 및 썸네일 (Previews &amp; Thumbnails)&quot;">​</a></h2><ul><li><strong>파일 미리보기 제공자 순서</strong>: 내장 미디어 디코더와 타사 QuickLook 브리지 등의 호출 우선순위를 조정합니다.</li><li><strong>썸네일 제공자 순서</strong>: 파일 아이콘 및 썸네일 추출 컴포넌트의 우선순위를 조정합니다.</li></ul>',19)])])}const p=r(n,[["render",a]]);export{h as __pageData,p as default};
